// checkoutReferencedHelmValueRepos resolves and checks out the repositories that are actually referenced from the given
// Helm value files (using the "$refname/path/to/file.yaml" syntax) so that their value files can be read. Referenced
// sources declared in the query's RefSources but not used in any value file are ignored - no git operations are
// performed for them.
//
// Ref source names are processed in lexicographically sorted order so that, when a conflict is detected, the resulting
// error message is deterministic (it reports the alphabetically later name first and the previously-seen name second).
//
// The returned closers hold the repository locks acquired for the checked-out repositories and must be closed by the
// caller once the referenced value files are no longer needed. Any closers already acquired are returned even when an
// error occurs so that the caller can always release them.
func (s *Service) checkoutReferencedHelmValueRepos(valueFiles []string, sha string, targetRevision string, q *apiclient.RepoServerAppDetailsQuery, tempPaths utilio.TempPaths) ([]goio.Closer, error) {
	var closers []goio.Closer

	// Determine which ref sources are actually referenced by the value files.
	referencedRefs := make(map[string]bool)
	for _, valueFile := range valueFiles {
		if !strings.HasPrefix(valueFile, "$") {
			continue
		}
		referencedRefs[strings.Split(valueFile, "/")[0]] = true
	}
	if len(referencedRefs) == 0 {
		return closers, nil
	}

	refNames := make([]string, 0, len(referencedRefs))
	for refName := range referencedRefs {
		refNames = append(refNames, refName)
	}
	sort.Strings(refNames)

	repoRefs := make(map[string]repoRef)
	for _, refName := range refNames {
		refSourceMapping, ok := q.RefSources[refName]
		if !ok {
			// The value file references a source that is not declared in RefSources. Resolution of the value file
			// itself will surface a meaningful error later, so there is nothing to check out here.
			continue
		}

		// Non-git referenced repositories (e.g. OCI) are not checked out - their contents are already available on
		// disk, so we only look up the cached path for them.
		if refSourceMapping.Repo.Type != "" && refSourceMapping.Repo.Type != "git" {
			tempPaths.GetPathIfExists(git.NormalizeGitURL(refSourceMapping.Repo.Repo))
			continue
		}

		normalizedRepoURL := git.NormalizeGitURL(refSourceMapping.Repo.Repo)

		gitClient, referencedCommitSHA, err := s.newClientResolveRevision(&refSourceMapping.Repo, refSourceMapping.TargetRevision, git.WithCache(s.cache, !q.NoRevisionCache && !q.NoCache))
		if err != nil {
			return closers, fmt.Errorf("error setting up git client for %s and resolving revision %s: %w", refSourceMapping.Repo.Repo, refSourceMapping.TargetRevision, err)
		}

		// If we have already resolved this repository for an earlier (alphabetically prior) ref source, make sure the
		// two references agree on the revision before reusing the existing checkout.
		if seen, ok := repoRefs[normalizedRepoURL]; ok {
			if seen.commitSHA != referencedCommitSHA {
				return closers, fmt.Errorf("cannot reference multiple revisions for the same repository (%s references %q which resolves to %q while %s references %q which resolves to %q)", refName, refSourceMapping.TargetRevision, referencedCommitSHA, seen.key, seen.revision, seen.commitSHA)
			}
			continue
		}

		// A referenced source may not point at a different revision of the main application's repository.
		if git.NormalizeGitURL(q.Repo.Repo) == normalizedRepoURL && sha != referencedCommitSHA {
			return closers, fmt.Errorf("cannot reference a different revision of the same repository (%s references %q which resolves to %q while the application references %q which resolves to %q)", refName, refSourceMapping.TargetRevision, referencedCommitSHA, targetRevision, sha)
		}

		closer, err := s.repoLock.Lock(gitClient.Root(), referencedCommitSHA, true, func(clean bool) (goio.Closer, error) {
			return s.checkoutRevision(gitClient, referencedCommitSHA, s.initConstants.SubmoduleEnabled, q.Repo.Depth, clean)
		})
		if err != nil {
			return closers, fmt.Errorf("failed to acquire lock for referenced repo %s: %w", refSourceMapping.Repo.Repo, err)
		}
		closers = append(closers, closer)

		// Symlink check must happen after acquiring the lock and checking out the revision.
		if !s.initConstants.AllowOutOfBoundsSymlinks {
			if err := apppathutil.CheckOutOfBoundsSymlinks(gitClient.Root()); err != nil {
				oobError := &apppathutil.OutOfBoundsSymlinkError{}
				if errors.As(err, &oobError) {
					log.WithFields(log.Fields{
						common.SecurityField: common.SecurityHigh,
						"repo":               refSourceMapping.Repo,
						"revision":           refSourceMapping.TargetRevision,
						"file":               oobError.File,
					}).Warn("repository contains out-of-bounds symlink")
					return closers, fmt.Errorf("repository contains out-of-bounds symlinks. file: %s", oobError.File)
				}
				return closers, err
			}
		}

		repoRefs[normalizedRepoURL] = repoRef{revision: refSourceMapping.TargetRevision, commitSHA: referencedCommitSHA, key: refName}
	}

	return closers, nil
}

